from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way, phoenix_gyro_turn

# Set up.
right_drive = Motor(Port.F, Direction.CLOCKWISE)
left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_attachment = Motor(Port.E, Direction.CLOCKWISE)
left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(left_drive, right_drive, 62.4, 90)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.settings(turn_rate=90)
drive_base.straight(-15)
right_attachment.run_angle(50, 85)
drive_base.straight(215)
phoenix_gyro_spin_turn_the_old_way(100, 20, 30, 40, 'right', drive_base, left_drive, right_drive)
wait(1000)
print(drive_base.angle())
drive_base.straight(565)
phoenix_gyro_spin_turn_the_old_way(100, -20, 30, -40, 'left', drive_base, left_drive, right_drive)
wait(1000)
print(drive_base.angle())
print(drive_base.angle())
drive_base.settings(straight_speed=50)
drive_base.straight(75)
